import { useTheme } from 'styled-components';

import { StaffClef } from './clefs';

export const Clef = ({ clef, y }: { clef: StaffClef; y: number }) => {
  const theme = useTheme();
  if (clef === 'bass')
    return (
      <g
        role="img"
        aria-label="Bass clef"
        transform={`translate(25 ${y})`}
        fill="currentColor"
      >
        {/* The curl and the midpoint between the dots mark the F3 line. */}
        <path d="M 0 0 C 0 -7 11 -12 17 -6 C 23 1 17 16 0 25 C 13 12 16 5 13 -2 C 11 -8 3 -8 2 -2 C 4 -5 8 -4 8 0 C 8 5 0 5 0 0 Z" />
        <circle cx="22" cy="-5" r="1.6" />
        <circle cx="22" cy="5" r="1.6" />
      </g>
    );
  return (
    <image
      role="img"
      aria-label="Treble clef"
      href={`${process.env.PUBLIC_URL}/clef-g${
        theme.key === 'dark' ? '-white' : ''
      }.svg`}
      x="25"
      // The curl at y=24 in the 16×42 glyph marks the G4 line.
      y={y - 24 * 1.5}
      width="24"
      height="63"
    />
  );
};
