import { useCallback, useEffect, useRef, useState } from 'react';
import styled from 'styled-components';

import { createDrumOutput } from 'app/services/DrumMachineService/audio';
import {
  DrumTrack,
  defaultDrumState,
} from 'app/services/DrumMachineService/patterns';
import {
  DrumOutput,
  createDrumTransport,
} from 'app/services/DrumMachineService/transport';
import { loadSound, resumeAudio } from 'app/services/SynthesizerService';

import { getDrumSamplePresentation } from './DrumSamplePicker/catalog';
import {
  DemoButton,
  DemoHint,
  DemoStatus,
  DemoSurface,
} from './LandingDemoStyles';

const bpm = 110;
const steps = 16;
const bands = [0, 8];
const trackLabels: Record<string, string> = {
  kick: 'Kick',
  snare: 'Snare',
  closedHat: 'Hi-hat',
  openHat: 'Open hat',
};

type Run = {
  output?: DrumOutput;
  transport?: ReturnType<typeof createDrumTransport>;
};

export const LandingDrums = ({ visible }: { visible: boolean }) => {
  const [beat, setBeat] = useState(() => defaultDrumState());
  const current = useRef(beat);
  const run = useRef<Run>();
  const [failed, setFailed] = useState(false);
  const [step, setStep] = useState(-1);
  const [focused, setFocused] = useState(0);
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);

  const clearRun = useCallback(() => {
    const previous = run.current;
    run.current = undefined;
    previous?.transport?.stop();
    previous?.output?.dispose();
  }, []);

  const stop = useCallback(() => {
    clearRun();
    setFailed(false);
    setStep(-1);
  }, [clearRun]);

  useEffect(() => clearRun, [clearRun]);
  useEffect(() => {
    void loadSound('drums').catch(() => {});
  }, []);
  useEffect(() => {
    if (!visible) stop();
  }, [visible, stop]);

  const start = async () => {
    if (run.current) return;

    const request: Run = {};
    run.current = request;
    setFailed(false);
    try {
      const [, output] = await Promise.all([
        resumeAudio(),
        createDrumOutput().then(kit => {
          if (run.current === request) request.output = kit;
          else kit.dispose();
          return kit;
        }),
      ]);
      if (run.current !== request) return;
      request.transport = createDrumTransport(
        output,
        () => ({ ...current.current, bpm, steps }),
        position => {
          if (run.current === request) setStep(position);
        },
      );
      request.transport.start();
    } catch {
      if (run.current !== request) return;
      clearRun();
      setStep(-1);
      setFailed(true);
    }
  };

  const toggleStep = (track: DrumTrack, position: number) => {
    if (!visible) return;
    const previous = current.current;
    const next = {
      ...previous,
      pattern: {
        ...previous.pattern,
        [track]: previous.pattern[track].map((on, slot) =>
          slot === position ? !on : on,
        ),
      },
    };
    current.current = next;
    setBeat(next);
    void start();
  };

  return (
    <div role="group" aria-label="Drum machine">
      <BeatSurface>
        <Bands role="group" aria-label="Beat steps">
          {bands.map(first => (
            <Band key={first} data-second={first > 0}>
              <TrackPicture />
              {Array.from({ length: 8 }, (_, i) => (
                <BeatNumber key={i} aria-hidden="true">
                  {i % 4 === 0 ? (first + i) / 4 + 1 : ''}
                </BeatNumber>
              ))}
              {beat.tracks.map((track, row) => (
                <Track key={track}>
                  <TrackPicture
                    aria-hidden="true"
                    title={trackLabels[track]}
                    data-open-hat={track === 'openHat' || undefined}
                  >
                    <img
                      src={getDrumSamplePresentation(beat.samples[track]).image}
                      alt=""
                    />
                  </TrackPicture>
                  {Array.from({ length: 8 }, (_, i) => {
                    const position = first + i;
                    const index = row * steps + position;
                    return (
                      <Step
                        key={position}
                        type="button"
                        ref={button => {
                          buttons.current[index] = button;
                        }}
                        tabIndex={index === focused ? 0 : -1}
                        onFocus={() => setFocused(index)}
                        aria-label={`${trackLabels[track]}, step ${
                          position + 1
                        }`}
                        aria-pressed={beat.pattern[track][position]}
                        data-current={step === position}
                        data-downbeat={position % 4 === 0}
                        onClick={() => toggleStep(track, position)}
                        onKeyDown={event => {
                          const nextRow =
                            row +
                            (event.key === 'ArrowUp'
                              ? -1
                              : event.key === 'ArrowDown'
                              ? 1
                              : 0);
                          const nextStep =
                            position +
                            (event.key === 'ArrowLeft'
                              ? -1
                              : event.key === 'ArrowRight'
                              ? 1
                              : 0);
                          if (nextRow === row && nextStep === position) return;
                          event.preventDefault();
                          if (
                            nextRow >= 0 &&
                            nextRow < beat.tracks.length &&
                            nextStep >= 0 &&
                            nextStep < steps
                          ) {
                            buttons.current[
                              nextRow * steps + nextStep
                            ]?.focus();
                          }
                        }}
                      />
                    );
                  })}
                </Track>
              ))}
            </Band>
          ))}
        </Bands>
      </BeatSurface>
      <DemoHint>Press a step to play and edit the beat.</DemoHint>
      <DemoStatus role="status">
        {failed && 'Could not start the beat. Press a step to try again.'}
      </DemoStatus>
    </div>
  );
};

const splitBeat =
  '(max-width: 520px), (min-width: 901px) and (max-width: 1120px)';

const BeatSurface = styled(DemoSurface)`
  padding: 10px 7px;

  @media ${splitBeat} {
    padding-inline: 4px;
  }
`;

const Bands = styled.div`
  display: grid;
  grid-template-columns: minmax(0, calc(50% + 24px)) minmax(0, 1fr);
  gap: 4px;

  @media ${splitBeat} {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }
`;

const TrackPicture = styled.span`
  position: relative;
  place-self: center;
  display: grid;
  place-items: center;
  width: 33px;
  height: 28px;

  &:empty {
    height: auto;
  }

  img {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }

  &[data-open-hat='true']::after {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    width: 8px;
    height: 8px;
    border: 1px solid #cce9e2;
    border-radius: 50%;
    background: #14282e;
  }
`;

const Band = styled.div`
  display: grid;
  grid-template-columns: 48px repeat(8, minmax(0, 1fr));
  gap: 3px;

  &[data-second='true'] {
    grid-template-columns: repeat(8, minmax(0, 1fr));

    ${TrackPicture} {
      display: none;
    }
  }

  @media ${splitBeat} {
    column-gap: 2px;

    &[data-second='true'] {
      grid-template-columns: 48px repeat(8, minmax(0, 1fr));

      ${TrackPicture} {
        display: grid;
      }
    }
  }
`;

const Track = styled.div`
  display: contents;
`;

const BeatNumber = styled.span`
  color: #a4c4bd;
  font: 700 0.625rem/1.4 ui-monospace, monospace;
  text-align: center;
`;

const Step = styled(DemoButton)`
  min-height: 29px;
  padding: 0;
  border-color: #35525b;
  border-radius: 4px;

  &[data-downbeat='true'] {
    border-color: #6c928e;
  }

  &[aria-pressed='true'] {
    background: #57d7bd;
    border-color: #57d7bd;
  }

  &[data-current='true'] {
    box-shadow: inset 0 0 0 2px #e2f1ec;
  }
`;
