import { Link } from 'react-router-dom';
import styled, { css } from 'styled-components';

const iconControl = css`
  && {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 48px;
    width: 48px;
    height: 48px;
    min-width: 48px;
    min-height: 48px;
    padding: 0;
    box-sizing: border-box;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: ${p => p.theme.textSecondary};
    text-decoration: none;
    cursor: pointer;

    &:visited {
      color: ${p => p.theme.textSecondary};
    }

    &:hover,
    &:focus-visible,
    &[aria-expanded='true'],
    &[aria-pressed='true'],
    &[aria-current='page'],
    &[data-active='true'] {
      border: 0;
      background: transparent;
      color: ${p => p.theme.primary};
    }

    &[aria-current='page']::before {
      content: '';
      position: absolute;
      bottom: 3px;
      width: 4px;
      height: 4px;
      border-radius: 50%;
      background: currentColor;
    }
  }
`;

export const HeaderIconButton = styled.button.attrs({
  'data-header-control': true,
})`
  ${iconControl}
`;

export const HeaderIconLink = styled(Link).attrs({
  'data-header-control': true,
})`
  ${iconControl}
`;
