import { ReactNode, createContext, useContext } from 'react';

import { useDrumMachinePlayback } from './useDrumMachine';

const DrumMachineContext = createContext<ReturnType<
  typeof useDrumMachinePlayback
> | null>(null);

export const DrumMachineProvider = ({ children }: { children: ReactNode }) => {
  const playback = useDrumMachinePlayback();
  return (
    <DrumMachineContext.Provider value={playback}>
      {children}
    </DrumMachineContext.Provider>
  );
};

export const useDrumMachine = () => {
  const playback = useContext(DrumMachineContext);
  if (!playback) throw new Error('DrumMachineProvider is required');
  return playback;
};
