import { range } from 'ramda';

import { scales } from 'app/services/SettingsService/scales';

import { JustNote } from './types';

const kammerton = {
  frequency: 440, // https://ru.wikipedia.org/wiki/A440
  noteName: 'A',
  baseOctaveNumber: 4, // https://ru.wikipedia.org/wiki/Октавная_система#Научная_нотация
};
const notesAmount = scales.chromatic.intervals.length;
const getNoteFrequency = (halftonesAmount: number) =>
  // https://ru.wikipedia.org/wiki/Равномерно_темперированный_строй#Вычисление_частот_звуков
  kammerton.frequency * 2 ** (halftonesAmount / notesAmount);
const minOctaveNumber = 0;
const maxOctaveNumber = 8;
const octavesList = range(minOctaveNumber, maxOctaveNumber + 1);
const baseNoteIndex = scales.chromatic.intervals.findIndex(
  noteName => noteName === kammerton.noteName,
);

export const tone = scales.chromatic.intervals.reduce(
  (dict, noteName, noteIndex) => {
    dict[noteName] = octavesList.map(o =>
      getNoteFrequency(
        notesAmount * (o - kammerton.baseOctaveNumber) +
          (noteIndex - baseNoteIndex),
      ),
    );
    return dict;
  },
  {} as Record<JustNote, number[]>,
);
