import { createSelector } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { initialState } from './slice';

const selectSlice = (state: RootState) => state.effects ?? initialState;

const selectInstruments = createSelector(
  [
    (state: RootState) => selectSlice(state).instruments,
    (state: RootState) => selectSlice(state).melody,
  ],
  (instruments, melody) =>
    melody ? { ...instruments, [melody.timbre]: melody.settings } : instruments,
);

export const selectEffects = createSelector(
  [selectSlice, selectInstruments],
  (state, instruments) => (state.melody ? { ...state, instruments } : state),
);
