import { useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  KeyCode,
  keyboardButtons,
  selectKeyboard,
} from 'app/services/KeyboardService';
import { getKeyboardNote } from 'app/services/KeyboardService/noteByKey';
import { selectSettings } from 'app/services/SettingsService';
import {
  noteTuningCents,
  tuningLabel,
} from 'app/services/SettingsService/microtonal';

import { KeyboardKey } from './KeyboardKey';

export const Keyboard = ({ keyboardWarning }) => {
  const { pressedKeys } = useSelector(selectKeyboard);
  const settings = useSelector(selectSettings);
  const keys = Object.keys(keyboardButtons) as KeyCode[];

  return (
    <KeyboardWrapper>
      {keyboardWarning ? (
        <KeyboardWarning>(!) {keyboardWarning}</KeyboardWarning>
      ) : null}

      {keys.map(code => (
        <KeyboardKey
          key={code}
          code={code}
          isPressed={pressedKeys.includes(code)}
          isHighlighted={!!getKeyboardNote(code, settings)}
          noteLabel={(() => {
            const note = getKeyboardNote(code, settings);
            if (!note) return undefined;
            const cents = noteTuningCents(note, settings);
            return `${note}${cents ? ` ${tuningLabel(cents)}` : ''}`;
          })()}
        />
      ))}
    </KeyboardWrapper>
  );
};

const KeyboardWrapper = styled.div`
  position: relative;
  user-select: none;
`;

const KeyboardWarning = styled.div`
  background-color: ${p => p.theme.warningBackground};
  color: ${p => p.theme.warning};
  position: relative;
  top: -30px;
  left: -50px;
`;
