import { useMemo } from 'react';
import { batch, useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { applicatures } from 'app/services/KeyboardService/mappings';
import {
  isMelodyKeyboardPlayable,
  melodyKeyIndices,
  optimizeMelodyScale,
  scaleLabels,
} from 'app/services/MelodiesService/scaleOptimization';
import type { Melody } from 'app/services/MelodiesService/types';
import { notesActions } from 'app/services/NotesService';
import { selectSettings, settingsActions } from 'app/services/SettingsService';
import { getScale } from 'app/services/SettingsService/scales';
import { fixedNotesFor } from 'app/services/SynthesizerService/timbres';

export const MelodyScaleOptimization = ({
  melody,
  recording = false,
  disabled = false,
  onStop,
}: {
  melody: Melody;
  recording?: boolean;
  disabled?: boolean;
  onStop: () => void;
}) => {
  const dispatch = useDispatch();
  const settings = useSelector(selectSettings);
  const optimized = useMemo(() => optimizeMelodyScale(melody), [melody]);
  if (
    !melody.notes.length ||
    settings.isRecording ||
    melody.timbre === 'drums' ||
    fixedNotesFor(settings.timbre) ||
    fixedNotesFor(melody.timbre)
  )
    return null;
  const current = {
    ...melody,
    scale: settings.scale,
    mode: settings.mode,
    pitch: settings.pitch,
    octave: settings.octave,
    customScale: settings.customScale,
    keyboardStart: undefined,
    keyboardLayout:
      settings.applicature.length === applicatures.totalQwertyMac.length
        ? ('full' as const)
        : undefined,
  };
  const size = getScale(
    optimized.scale,
    optimized.mode,
    optimized.customScale,
  ).length;
  // Also respect user-defined shorter applicatures, rather than just the default.
  const playable = melodyKeyIndices(current).every(
    index => index >= 0 && index < settings.applicature.length,
  );
  const shouldOffer = settings.scaleNotes.length > size || !playable;
  if (!shouldOffer || !isMelodyKeyboardPlayable(optimized)) return null;
  return (
    <Suggestion aria-label="Scale selection">
      <span>
        Easier to play: {scaleLabels[optimized.scale]} · {size} degrees
        {size < settings.scaleNotes.length
          ? ` instead of ${settings.scaleNotes.length}`
          : ', all notes on the keyboard'}
        . All notes will be preserved.
      </span>
      <button
        type="button"
        disabled={disabled}
        onClick={() => {
          onStop();
          batch(() => {
            if (recording) dispatch(notesActions.setRecordingScale(optimized));
            dispatch(
              settingsActions.loadMelodySettings({
                ...optimized,
                bpm: settings.bpm,
                timbre: settings.timbre,
                timeSignature: settings.timeSignature,
              }),
            );
          });
        }}
      >
        Optimize scale
      </button>
    </Suggestion>
  );
};

const Suggestion = styled.aside`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  margin: 8px 0;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  button {
    font-size: inherit;
  }
`;
