import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import { formatPitch } from 'app/services/ChordsService';
import { useLibraryPlayback } from 'app/services/MelodiesService/useLibraryPlayback';
import { downloadBlob } from 'app/services/MelodyExportService';
import {
  Phrase,
  composePhrase,
} from 'app/services/MelodyGenerationService/compose';
import {
  encodePhraseMidi,
  phrasePlayback,
} from 'app/services/MelodyGenerationService/output';

import { PageWrapper } from 'app/components/_styled/PageWrapper';

const examples = [
  'Calm piano in C major, 4 bars',
  'Upbeat pop in G major, 120 BPM',
  'Cinematic in D minor, 95 BPM',
  'Lo-fi in F minor, 8 bars',
];

export const MelodyGeneratorPage = () => {
  const [prompt, setPrompt] = useState('');
  const [phrase, setPhrase] = useState<Phrase>();
  const [previewAttempted, setPreviewAttempted] = useState(false);
  const playback = useLibraryPlayback();

  return (
    <Page>
      <Helmet>
        <title>Generate a melody</title>
        <meta
          name="description"
          content="Describe a melody, listen to it with chords, and download both parts as a MIDI file."
        />
      </Helmet>
      <header>
        <h1>Generate a melody</h1>
        <p>
          Describe a mood or style. The generator creates a melody and
          accompaniment in your browser.
        </p>
      </header>
      <Panel
        as="form"
        onSubmit={event => {
          event.preventDefault();
          if (!prompt.trim()) return;
          playback.stop();
          setPreviewAttempted(false);
          setPhrase(composePhrase(prompt));
        }}
      >
        <label htmlFor="melody-prompt">Melody description</label>
        <textarea
          id="melody-prompt"
          aria-describedby="melody-prompt-help"
          value={prompt}
          onChange={event => setPrompt(event.target.value)}
          maxLength={300}
          required
          rows={3}
        />
        <p id="melody-prompt-help">
          Try one of these examples, or specify a key, tempo and 4 to 16 bars.
        </p>
        <Actions>
          {examples.map(example => (
            <button
              key={example}
              type="button"
              onClick={() => setPrompt(example)}
            >
              {example}
            </button>
          ))}
        </Actions>
        <Actions>
          <button type="submit" className="selected" disabled={!prompt.trim()}>
            Generate melody
          </button>
        </Actions>
      </Panel>
      {phrase && (
        <Panel aria-labelledby="generated-melody">
          <h2 id="generated-melody">Your melody</h2>
          <p role="status">
            {phrase.style} · {formatPitch(phrase.tonic)} {phrase.mode} ·{' '}
            {phrase.bpm} BPM · {phrase.bars} bars in 4/4
          </p>
          <h3>Chord progression</h3>
          <Progression>
            {phrase.chords.map((chord, bar) => (
              <li key={bar}>
                <span>Bar {bar + 1}</span> <strong>{chord}</strong>
              </li>
            ))}
          </Progression>
          <Actions>
            <button
              type="button"
              onClick={() => {
                if (playback.activeTitle) playback.stop();
                else {
                  setPreviewAttempted(true);
                  void playback.toggle(phrasePlayback(phrase));
                }
              }}
            >
              {playback.activeTitle ? 'Stop preview' : 'Play preview'}
            </button>
            <button
              type="button"
              onClick={() =>
                downloadBlob(
                  new Blob([encodePhraseMidi(phrase)], { type: 'audio/midi' }),
                  'generated-melody.mid',
                )
              }
            >
              Download MIDI
            </button>
          </Actions>
          {playback.loading && <p role="status">Loading sound…</p>}
          {previewAttempted && playback.error && (
            <ErrorText role="alert">{playback.error}</ErrorText>
          )}
        </Panel>
      )}
    </Page>
  );
};

const Page = styled(PageWrapper)`
  max-width: 880px;
  display: grid;
  gap: 20px;

  h1 {
    margin: 0 0 6px;
    text-align: left;
    font-family: inherit;
    font-size: clamp(28px, 4vw, 44px);
    font-weight: 680;
  }

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
  }
`;

const Panel = styled.section`
  display: grid;
  gap: 12px;
  padding: clamp(12px, 3vw, 20px);
  border: 1px solid ${p => p.theme.border};
  border-radius: 14px;
  background: ${p => p.theme.surface};

  h2 {
    font-size: 20px;
  }

  h3,
  label {
    font-size: 16px;
    font-weight: 650;
  }

  textarea {
    min-width: 0;
    padding: 10px 12px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 8px;
    background: ${p => p.theme.backgroundVariant};
    color: ${p => p.theme.text};
    font: inherit;
    font-size: 16px;
    resize: vertical;
  }
`;

const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
`;

const Progression = styled.ol`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(64px, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;

  li {
    display: grid;
    gap: 4px;
    padding: 8px;
    border-radius: 8px;
    background: ${p => p.theme.backgroundVariant};
  }

  span {
    color: ${p => p.theme.textSecondary};
    font-size: 12px;
  }
`;

const ErrorText = styled.p`
  && {
    color: ${p => p.theme.danger};
  }
`;
