import {
  chordSymbol,
  diatonicChords,
  pitchClass,
} from 'app/services/ChordsService';

import { parsePrompt } from './prompt';

export const STEPS_PER_BAR = 8;
export const STEPS_PER_BEAT = 2;

export interface PhraseNote {
  midi: number;
  start: number;
  length: number;
}

const motifs = [
  [2, 4, 5, 4, 3, 2, 1],
  [4, 3, 2, 4, 5, 4, 2],
  [1, 2, 4, 3, 5, 6, 4],
];

export const composePhrase = (description: string, random = Math.random) => {
  const { style, tonic, mode, bpm, bars } = parsePrompt(description);
  const scale = diatonicChords(tonic, mode);
  const pitch = pitchClass(tonic);
  const scaleOffsets = scale.map(
    chord => (pitchClass(chord.root) - pitch + 12) % 12,
  );
  const base = 60 + pitch;
  const midiFor = (step: number) =>
    base + scaleOffsets[step % 7] + 12 * Math.floor(step / 7);
  const progressions = style.progressions[mode];
  const pattern = progressions[Math.floor(random() * progressions.length)];
  const motif = motifs[Math.floor(random() * motifs.length)];
  const degrees = Array.from(
    { length: bars },
    (_, bar) => pattern[bar % pattern.length],
  );
  degrees[bars - 2] = degrees[bars - 3] === 4 ? 3 : 4;
  degrees[bars - 1] = 0;

  const melody: PhraseNote[] = [];
  const accompaniment: PhraseNote[] = [];
  let previous = motif[0];
  degrees.forEach((degree, bar) => {
    const offset = bar * STEPS_PER_BAR;
    const final = bar === bars - 1;
    const rhythm = final ? [0, 2, 4] : style.rhythms[bar % 2];
    const chordSteps = Array.from({ length: 10 }, (_, step) => step).filter(
      step => [degree, (degree + 2) % 7, (degree + 4) % 7].includes(step % 7),
    );
    const steps = rhythm.map((_, i) => {
      if (final && i === rhythm.length - 1) return previous < 4 ? 0 : 7;
      const target = motif[i] + (bar % 4 === 2 ? 1 : 0);
      const cost = (step: number) =>
        2 * Math.abs(step - target) + Math.abs(step - previous);
      previous = chordSteps.reduce((best, step) =>
        cost(step) < cost(best) ? step : best,
      );
      return previous;
    });

    rhythm.forEach((onset, i) => {
      let step = steps[i];
      // A non-chord tone sits between two chord tones one eighth note apart.
      if (
        onset % 2 === 1 &&
        rhythm[i - 1] === onset - 1 &&
        rhythm[i + 1] === onset + 1
      ) {
        const before = steps[i - 1];
        const after = steps[i + 1];
        if (Math.abs(before - after) === 2) step = (before + after) / 2;
        else if (before === after) step = before === 0 ? 1 : before - 1;
      }
      melody.push({
        midi: midiFor(step),
        start: offset + onset,
        length: (rhythm[i + 1] ?? STEPS_PER_BAR) - onset,
      });
    });

    const chord = [degree, degree + 2, degree + 4].map(
      step => 48 + (midiFor(step) % 12),
    );
    const bass = { midi: chord[0] - 12, start: offset, length: STEPS_PER_BAR };
    accompaniment.push(bass);
    const backing = final ? [0] : style.backing;
    backing.forEach((onset, i) => {
      const pitches =
        style.brokenChord && !final ? [chord[i % chord.length]] : chord;
      const span = (backing[i + 1] ?? STEPS_PER_BAR) - onset;
      const length =
        backing.length > 1 && !style.brokenChord ? Math.min(span, 2) : span;
      pitches.forEach(midi =>
        accompaniment.push({ midi, start: offset + onset, length }),
      );
    });
  });

  return {
    bpm,
    bars,
    mode,
    pitch,
    tonic,
    style: style.label,
    chords: degrees.map(degree => chordSymbol(scale[degree])),
    melody,
    accompaniment,
  };
};

export type Phrase = ReturnType<typeof composePhrase>;
