import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';
import type { Melody } from 'app/services/MelodiesService/types';

const MAX_MEASURES = 8;

// A long pause or sustain cannot expand the live staff by hundreds of bars.
export const getLiveStaffPreview = (melody: Melody, bpm: number) => {
  const measureDuration =
    (60000 / bpm) * getBeatsPerMeasure(melody.timeSignature);
  const latestStart = melody.notes.reduce(
    (latest, note) => Math.max(latest, note.start),
    0,
  );
  const measureOffset = Math.max(
    0,
    Math.floor(latestStart / measureDuration) - MAX_MEASURES + 1,
  );
  const from = measureOffset * measureDuration;
  const maxTime = MAX_MEASURES * measureDuration;
  const notes = melody.notes
    .filter(note => note.start >= from)
    .map(note => ({ ...note, start: note.start - from }));
  const firstStart = (melody.firstStart ?? 0) + from;
  return {
    melody: { ...melody, firstStart, notes },
    measureOffset,
    maxTime,
    omittedNotes: notes.length !== melody.notes.length,
    end: firstStart + maxTime,
  };
};
