import { useId, useRef, useState } from 'react';
import styled, { keyframes } from 'styled-components';

import { resumeAudio } from 'app/services/SynthesizerService';

import { DemoButton } from './LandingDemoStyles';
import { LandingDrums } from './LandingDrums';
import { LandingGuitar } from './LandingGuitar';
import { LandingPiano } from './LandingPiano';

const slides = ['Piano', 'Guitar', 'Drums'] as const;
type Slide = typeof slides[number];

export const LandingInstruments = () => {
  const id = useId();
  const [active, setActive] = useState<Slide>('Piano');
  const tabs = useRef<(HTMLButtonElement | null)[]>([]);
  const selectInstrument = (slide: Slide) => {
    if (slide === 'Guitar') {
      // A tab click lets the first touch on the fretboard play while held.
      void resumeAudio().catch(() => {});
    }
    setActive(slide);
  };

  return (
    <InstrumentCard>
      <TabList role="tablist" aria-label="Try an instrument">
        {slides.map((slide, index) => (
          <Chip
            key={slide}
            ref={element => {
              tabs.current[index] = element;
            }}
            type="button"
            role="tab"
            id={`${id}-tab-${slide}`}
            aria-controls={`${id}-panel-${slide}`}
            aria-selected={active === slide}
            tabIndex={active === slide ? 0 : -1}
            onClick={() => selectInstrument(slide)}
            onKeyDown={event => {
              let next: number;
              switch (event.key) {
                case 'ArrowLeft':
                  next = (index + slides.length - 1) % slides.length;
                  break;
                case 'ArrowRight':
                  next = (index + 1) % slides.length;
                  break;
                case 'Home':
                  next = 0;
                  break;
                case 'End':
                  next = slides.length - 1;
                  break;
                default:
                  return;
              }
              event.preventDefault();
              selectInstrument(slides[next]);
              tabs.current[next]?.focus();
            }}
          >
            {slide}
          </Chip>
        ))}
      </TabList>
      <SlideStack>
        {slides.map(slide => {
          const visible = active === slide;
          return (
            <SlidePanel
              key={slide}
              id={`${id}-panel-${slide}`}
              role="tabpanel"
              aria-labelledby={`${id}-tab-${slide}`}
              aria-hidden={visible ? undefined : true}
              {...(visible ? {} : { inert: '' })}
            >
              {slide === 'Piano' && <LandingPiano visible={visible} />}
              {slide === 'Guitar' && <LandingGuitar visible={visible} />}
              {slide === 'Drums' && <LandingDrums visible={visible} />}
            </SlidePanel>
          );
        })}
      </SlideStack>
    </InstrumentCard>
  );
};

const InstrumentCard = styled.div`
  align-self: start;
  justify-self: center;
  width: 100%;
  max-width: 620px;
  padding: clamp(10px, 1.9vw, 18px) clamp(14px, 3vw, 28px);
  border: 1px solid #35525b;
  border-radius: 20px;
  background: radial-gradient(ellipse at 30% 0%, #22434a, #0d1c22 75%);
  box-shadow: 0 18px 44px ${p => p.theme.shadow};
`;

const TabList = styled.div`
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-bottom: 10px;
`;

const Chip = styled(DemoButton)`
  min-height: 36px;
  padding: 2px clamp(12px, 2vw, 16px);
  border-radius: 999px;

  &[aria-selected='true'] {
    background: #57d7bd;
    border-color: #57d7bd;
    color: #16363d;
  }
`;

const enter = keyframes`
  from { opacity: 0.6; transform: translateX(5px); }
  to { opacity: 1; transform: translateX(0); }
`;

const SlideStack = styled.div`
  display: grid;
`;

const SlidePanel = styled.div`
  grid-area: 1 / 1;
  display: flex;
  flex-direction: column;
  min-width: 0;

  &[aria-hidden='true'] {
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: no-preference) {
    &:not([aria-hidden='true']) {
      animation: ${enter} 160ms ease-out both;
    }
  }
`;
