export const ImportMelodyPage = () => (
  <PageWrapper>
    <FeatureHeading
      title="Import MIDI or Guitar Pro"
      description="Choose a file from your device, preview its tracks, and pick which track to open first."
    />
    <MelodyImport />
  </PageWrapper>
);

export const ExportMelodyPage = () => {
  const source = useSelector(selectCompletedRecording);
  const recording = useCurrentMelody(source);
  const library = useSelector(selectRecentLibraryMelodies).filter(
    melody => melody.notes.length,
  );
  const [selection, setSelection] = useState<string>();
  const hasRecording = !!recording?.notes.length;
  const melody =
    library.find(item => item.title === selection) ??
    (hasRecording ? recording : library[0]);

  return (
    <PageWrapper>
      <FeatureHeading
        title="Export your work"
        description="Download a melody as MIDI, WAV, or MP3, or save its sheet music or tabs as a PDF."
      />
      {melody && (
        <>
          <SourceField>
            Melody
            <select
              aria-label="Melody to export"
              value={melody === recording ? '' : melody.title}
              onChange={event => setSelection(event.target.value)}
            >
              {hasRecording && <option value="">Current recording</option>}
              {library.map(item => (
                <option key={item.title} value={item.title}>
                  {item.displayTitle ?? item.title}
                </option>
              ))}
            </select>
          </SourceField>
          <MelodyExport key={melody.title} melody={melody} />
        </>
      )}
    </PageWrapper>
  );
};

export const FlyingNotesPage = () => (
  <PageWrapper>
    <FeatureHeading
      title="Flying Notes"
      description="Press a key and hold it to see the note rise and its tail grow."
    />
    <FlyingNotes />
  </PageWrapper>
);

export const MetronomePage = () => (
  <NarrowPage>
    <FeatureHeading
      title="Metronome"
      description="Set the tempo, time signature, and rhythm. Start the click to hear the accents."
    />
    <MetronomeSlot />
  </NarrowPage>
);

export const ChordRecognitionPage = () => {
  const sounding = useSelector(selectSoundingNotes);
  const matches = detectChords(sounding).map(chordSymbol);

  return (
    <PageWrapper>
      <FeatureHeading
        title="Chord recognition"
        description="Hold three or four different notes on your computer keyboard, onscreen piano, or MIDI controller."
      />
      <ChordResult aria-live="polite" role="status">
        <strong>
          {matches.length
            ? matches.join(' / ')
            : sounding.length >= 3
            ? 'No exact match'
            : 'Play a chord'}
        </strong>
        {sounding.length > 0 && (
          <span>{sounding.map(formatPitch).join(' · ')}</span>
        )}
      </ChordResult>
      <SandboxInstrument inline />
      <Link to="/midi-audio-input">Connect a MIDI controller</Link>
    </PageWrapper>
  );
};

export const GuitarAmpPage = () => {
  const { stopAmpRecording } = useConnectedGuitarInput();
  useEffect(() => stopAmpRecording, [stopAmpRecording]);

  return (
    <PageWrapper>
      <FeatureHeading
        title="Use your computer as a guitar amp"
        description="Connect your guitar through an audio interface to hear it with effects. Record a take to download a clean or processed WAV."
      />
      <InputDevicesSlot placement="amp" />
    </PageWrapper>
  );
};

