import { useEffect, useRef } from 'react';
import styled from 'styled-components';

import { guitarStrings } from 'app/services/VirtualGuitarService/fretboard';
import {
  GuitarTabNote,
  guitarTabLength,
} from 'app/services/VirtualGuitarService/useVirtualGuitar';

import { DemoSurface } from '../LandingDemoStyles';

const stringLabels = guitarStrings.map((note, index) =>
  index === 0 ? 'e' : note[0],
);

const example: GuitarTabNote[] = [
  { id: 0, string: 5, fret: 0 },
  { id: 1, string: 4, fret: 2 },
  { id: 2, string: 3, fret: 2 },
  { id: 3, string: 2, fret: 0 },
  { id: 4, string: 1, fret: 0 },
  { id: 5, string: 0, fret: 0 },
  { id: 6, string: 1, fret: 0 },
  { id: 7, string: 2, fret: 0 },
];

const tabEntry = ({ fret, technique }: GuitarTabNote) => {
  const start = fret ? `fret ${fret}` : 'open';
  if (technique?.kind === 'bend') {
    const { cents, released } = technique;
    return {
      label: `${fret}b${cents}¢${released ? 'r' : ''}`,
      description: `${start}, bend up ${cents} cents${
        released ? ' and release' : ''
      }`,
    };
  }
  if (technique?.kind === 'slide') {
    let label = String(fret);
    let previous = fret;
    for (const target of technique.targets) {
      label += (target > previous ? '/' : '\\') + target;
      previous = target;
    }
    return {
      label,
      description: `${start}, slide to ${technique.targets.join(', then ')}`,
    };
  }
  return { label: String(fret), description: start };
};

export const GuitarTab = ({ notes }: { notes: GuitarTabNote[] }) => {
  const viewport = useRef<HTMLDivElement>(null);
  const entries = (notes.length ? notes : example).map(note => ({
    string: note.string,
    ...tabEntry(note),
  }));
  const slots = Array.from({ length: guitarTabLength }, (_, i) => entries[i]);
  const columns = [
    '24px',
    ...slots.map(entry => `minmax(${(entry?.label.length ?? 1) + 1}ch, 1fr)`),
  ].join(' ');

  useEffect(() => {
    const element = viewport.current;
    if (element && notes.length) element.scrollLeft = element.scrollWidth;
  }, [notes]);

  return (
    <Tab
      ref={viewport}
      role="img"
      aria-label={`Guitar tab: ${entries
        .map(
          ({ string, description }) => `string ${string + 1}, ${description}`,
        )
        .join('; ')}`}
    >
      {stringLabels.map((label, string) => (
        <TabLine
          key={guitarStrings[string]}
          aria-hidden="true"
          style={{ gridTemplateColumns: columns }}
        >
          <span>{label}</span>
          {slots.map((entry, index) =>
            entry?.string === string ? (
              <TabNumber key={index}>
                <span>{entry.label}</span>
              </TabNumber>
            ) : (
              <span key={index} />
            ),
          )}
        </TabLine>
      ))}
    </Tab>
  );
};

const Tab = styled(DemoSurface)`
  min-width: 0;
  padding: 6px 10px;
  overflow-x: auto;
  background: #11242a;
  font: 700 0.75rem/1 ui-monospace, monospace;
`;

const TabLine = styled.div`
  display: grid;
  align-items: center;
  justify-items: center;
  min-height: 14px;

  > span:first-child {
    position: sticky;
    left: 0;
    z-index: 1;
    width: 100%;
    background: #11242a;
    text-align: center;
  }

  > span:not(:first-child) {
    display: grid;
    place-items: center;
    width: 100%;
    min-height: 14px;
    background: linear-gradient(#50736f, #50736f) left center / 100% 1px
      no-repeat;
  }
`;

const TabNumber = styled.span`
  span {
    padding: 1px 3px;
    border-radius: 3px;
    background: #14282e;
    color: #e2f1ec;
    white-space: nowrap;
  }
`;
