import { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { scaleLabels } from 'app/services/MelodiesService/scaleOptimization';
import { Octave, pitchNote, splitNote } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNoteBindings } from 'app/services/PlayAlongService/game';
import {
  Mode,
  Scale,
  scales,
  selectSettings,
  settingsActions,
} from 'app/services/SettingsService';
import {
  isMicrotonalScale,
  microtonalInstrument,
  microtonalPreset,
} from 'app/services/SettingsService/microtonal';
import { fixedNotesFor } from 'app/services/SynthesizerService/timbres';
import type { Timbre } from 'app/services/SynthesizerService/types';

import { timbreOptions } from 'app/components/TimbrePicker/catalog';

const modeLabels: Partial<Record<Mode, string>> = {
  ionian: 'Ionian (major)',
  dorian: 'Dorian',
  phrygian: 'Phrygian',
  lydian: 'Lydian',
  mixolydian: 'Mixolydian',
  aeolian: 'Aeolian (minor)',
  locrian: 'Locrian',
  chromatic: 'Chromatic',
  custom: 'Composition notes',
  solo: '11 degrees',
  h1: 'Harmonic minor',
  j1: 'Melodic minor',
  p1: 'Major pentatonic',
  p5: 'Minor pentatonic',
};

export const SessionSettings = () => {
  const dispatch = useDispatch();
  const settings = useSelector(selectSettings);
  const { octave, pitch, scale, mode, timbre } = settings;
  const [pitchInput, setPitchInput] = useState(String(pitch));
  useEffect(() => setPitchInput(String(pitch)), [pitch]);
  const fixedNotes = fixedNotesFor(timbre);
  const tonic = splitNote(pitchNote('C4', pitch))[0];
  const canShift = (direction: number) => {
    const next = octave + direction;
    return (
      !fixedNotes &&
      next >= 0 &&
      next <= 8 &&
      Array.from(
        getNoteBindings({ ...settings, octave: next as Octave }).keys(),
      ).every(note => /^[A-G]#?[0-8]$/.test(note))
    );
  };
  const canLower = canShift(-1);
  const canRaise = canShift(1);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (
        event.repeat ||
        event.metaKey ||
        event.ctrlKey ||
        event.altKey ||
        (event.target instanceof HTMLElement &&
          event.target.closest(
            'input, select, textarea, [contenteditable="true"], [data-session-control]',
          ))
      )
        return;
      const direction =
        event.code === 'ArrowDown' ? -1 : event.code === 'ArrowUp' ? 1 : 0;
      if (!direction) return;
      event.preventDefault();
      if (direction < 0 ? canLower : canRaise)
        dispatch(settingsActions.setOctave((octave + direction) as Octave));
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [canLower, canRaise, dispatch, octave]);

  return (
    <Bar aria-label="Current settings">
      {!fixedNotes && (
        <OctaveControl aria-label="Octave controls">
          <span>Octave</span>
          <button
            type="button"
            aria-label="Octave down"
            aria-keyshortcuts="ArrowDown"
            title="Octave down (↓)"
            disabled={!canLower}
            onClick={() =>
              dispatch(settingsActions.setOctave((octave - 1) as Octave))
            }
          >
            −
          </button>
          <strong aria-label="Current octave">{octave + 1}</strong>
          <button
            type="button"
            aria-label="Octave up"
            aria-keyshortcuts="ArrowUp"
            title="Octave up (↑)"
            disabled={!canRaise}
            onClick={() =>
              dispatch(settingsActions.setOctave((octave + 1) as Octave))
            }
          >
            +
          </button>
        </OctaveControl>
      )}
      <Details data-session-control>
        {fixedNotes ? (
          <div>
            <dt>Tuning</dt>
            <dd>D minor · {fixedNotes.join(', ')}</dd>
          </div>
        ) : (
          <>
            <div role="group" aria-label="Key">
              <dt id="session-tonic-label">Key</dt>
              <dd>
                <select
                  aria-labelledby="session-tonic-label"
                  value={tonic}
                  onChange={({ target }) => {
                    const index = chromaticNotes.indexOf(
                      target.value as typeof tonic,
                    );
                    const next = [index - 12, index, index + 12]
                      .filter(value => value >= -12 && value <= 12)
                      .sort(
                        (a, b) => Math.abs(a - pitch) - Math.abs(b - pitch),
                      )[0];
                    dispatch(settingsActions.setPitch(next));
                  }}
                >
                  {chromaticNotes.map(note => (
                    <option key={note} value={note}>
                      {note}
                    </option>
                  ))}
                </select>
                <span aria-hidden="true">·</span>
                <select
                  aria-label="Mode"
                  value={mode}
                  onChange={({ target }) =>
                    dispatch(settingsActions.setMode(target.value as Mode))
                  }
                >
                  {scales[scale].modes.map(value => (
                    <option key={value} value={value}>
                      {microtonalPreset(scale, value)?.label ??
                        modeLabels[value] ??
                        value.toUpperCase()}
                    </option>
                  ))}
                </select>
              </dd>
            </div>
            <div>
              <dt id="session-scale-label">Scale</dt>
              <dd>
                <select
                  aria-labelledby="session-scale-label"
                  value={scale}
                  onChange={({ target }) =>
                    dispatch(settingsActions.setScale(target.value as Scale))
                  }
                >
                  {(Object.keys(scales) as Scale[])
                    .filter(
                      value =>
                        (value !== 'custom' || settings.customScale?.length) &&
                        (!isMicrotonalScale(value) ||
                          microtonalInstrument(timbre)?.scale === value ||
                          value === scale),
                    )
                    .map(value => (
                      <option key={value} value={value}>
                        {scaleLabels[value]}
                      </option>
                    ))}
                </select>
              </dd>
            </div>
          </>
        )}
        <div>
          <dt id="session-timbre-label">Instrument</dt>
          <dd>
            <select
              aria-labelledby="session-timbre-label"
              value={timbre}
              onChange={({ target }) =>
                dispatch(settingsActions.setTimbre(target.value as Timbre))
              }
            >
              {timbreOptions.map(option => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </select>
          </dd>
        </div>
        {!fixedNotes && (
          <div title="Semitone offset">
            <dt id="session-pitch-label">Transpose</dt>
            <dd>
              <input
                type="number"
                aria-labelledby="session-pitch-label"
                min={-12}
                max={12}
                step={1}
                value={pitchInput}
                onBlur={() => setPitchInput(String(pitch))}
                onChange={({ target }) => {
                  setPitchInput(target.value);
                  const value = target.valueAsNumber;
                  if (Number.isInteger(value) && value >= -12 && value <= 12)
                    dispatch(settingsActions.setPitch(value));
                }}
              />
              <span>st</span>
            </dd>
          </div>
        )}
      </Details>
    </Bar>
  );
};

const Bar = styled.section`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 18px;
  overflow-x: auto;
  padding: 3px;
  scrollbar-width: thin;
  white-space: nowrap;
  min-width: 0;
  font-size: 11px;
  line-height: 1.3;
`;
const OctaveControl = styled.div`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 5px;
  color: ${p => p.theme.textSecondary};
  button {
    width: 28px;
    height: 28px;
    min-height: 0;
    padding: 0;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    color: ${p => p.theme.text};
    background: transparent;
    font-size: 16px;
    &:disabled {
      opacity: 0.4;
      cursor: default;
    }
    &:focus-visible {
      outline: 2px solid ${p => p.theme.primary};
      outline-offset: 2px;
    }
  }
  strong {
    min-width: 16px;
    text-align: center;
    color: ${p => p.theme.text};
    font-variant-numeric: tabular-nums;
    font-weight: 500;
  }
`;
const Details = styled.dl`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 4px 16px;
  min-width: 0;
  margin: 0;
  div {
    display: flex;
    align-items: center;
    gap: 3px;
    min-width: 0;
  }
  dt {
    color: ${p => p.theme.textSecondary};
  }
  dd {
    display: flex;
    align-items: center;
    gap: 3px;
    margin: 0;
    color: ${p => p.theme.text};
  }
  select,
  input {
    min-height: 28px;
    padding: 3px 5px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    color: ${p => p.theme.text};
    background: ${p => p.theme.surface};
    font: inherit;
    &:focus-visible {
      outline: 2px solid ${p => p.theme.primary};
      outline-offset: 2px;
    }
  }
  select {
    max-width: 220px;
  }
  input {
    width: 56px;
  }
  @media (max-width: 600px) {
    gap: 4px 10px;
    font-size: 10px;
  }
  @media (max-height: 480px) {
    font-size: 10px;
    gap: 3px 10px;
  }
`;
