const solfege: Record<string, string> = {
  до: 'C',
  ре: 'D',
  ми: 'E',
  фа: 'F',
  соль: 'G',
  ля: 'A',
  си: 'B',
};
const accidentals: Record<string, string> = {
  '#': '#',
  sharp: '#',
  диез: '#',
  b: 'b',
  flat: 'b',
  бемоль: 'b',
};
const keyPattern =
  /(?:^|[^a-zа-яё0-9])([a-g]|до|ре|ми|фа|соль|ля|си)(?:[\s-]*(#|b|sharp|flat|диез|бемоль))?[\s-]+(major|minor|мажор[ае]?|минор[ае]?)(?![a-zа-яё])/;
const tempoPattern =
  /(?:^|[^a-zа-яё0-9])([0-9]+(?:[.,][0-9]+)?)\s*(?:bpm|бпм|ударов\s+в\s+минуту)(?![a-zа-яё])/;
const lengthPattern =
  /(?:^|[^a-zа-яё0-9])([0-9]+)\s*(?:bars?|measures?|такт(?:а|ов)?)(?![a-zа-яё])/;

export const parsePrompt = (description: string) => {
  const text = description
    .normalize('NFKC')
    .toLowerCase()
    .replace(/♯/g, '#')
    .replace(/♭/g, 'b');
  const words =
    text
      .replace(/\blo[-\s]fi\b/g, 'lofi')
      .replace(/\bhip[-\s]hop\b/g, 'hiphop')
      .match(/[a-zа-яё]+/g) ?? [];
  const style =
    styles.find(item => words.some(word => item.words.test(word))) ?? balanced;
  const key = text.match(keyPattern);
  const minor = /^(minor|минор[ае]?)$/;
  const major = /^(major|мажор[ае]?)$/;
  let mode = style.mode;
  if (key) mode = minor.test(key[3]) ? 'minor' : 'major';
  else if (words.some(word => minor.test(word))) mode = 'minor';
  else if (words.some(word => major.test(word))) mode = 'major';
  else if (words.some(word => /^(sad|грустн[а-я]*)$/.test(word)))
    mode = 'minor';

  const tonic = key
    ? (solfege[key[1]] ?? key[1].toUpperCase()) + (accidentals[key[2]] ?? '')
    : mode === 'minor'
    ? 'A'
    : 'C';
  const tempo = text.match(tempoPattern)?.[1];
  const bars = Number(text.match(lengthPattern)?.[1] ?? 8);
  let bpm = style.bpm;
  if (tempo) bpm = clampTempo(Number(tempo.replace(',', '.')));
  else if (words.some(word => /^(slow|медленн[а-я]*)$/.test(word))) bpm = 72;
  else if (words.some(word => /^(fast|быстр[а-я]*)$/.test(word))) bpm = 136;
  return { style, tonic, mode, bpm, bars: Math.max(4, Math.min(16, bars)) };
};
