const shortLabels: Record<string, string> = {
  'Pedal position': 'Pedal',
  'Wah rate': 'Rate',
  'Auto-sweep': 'Auto',
  'Distortion tone': 'Tone',
  'Chorus rate': 'Rate',
  'Chorus mix': 'Mix',
  'Delay mix': 'Mix',
  'Reverb mix': 'Mix',
  'Reverb tone': 'Tone',
};

const formatValue = (value: number, unit: string) => {
  const number = (next: number) => next.toLocaleString('en-US');
  if (unit === ':1') return `${number(value)}:1`;
  if (unit === 'Hz' && value >= 1000) return `${number(value / 1000)} kHz`;
  return `${unit === 'dB' && value > 0 ? '+' : ''}${number(value)} ${unit}`;
};

const formatScale = (value: number, unit: string) => {
  if (unit === 'Hz' && value >= 1000) {
    return `${(value / 1000).toLocaleString('en-US')}k`;
  }
  if (unit === 'ms' && value >= 1000) return `${value / 1000}s`;
  return value.toLocaleString('en-US');
};

const PowerIcon = () => (
  <svg
    width="14"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    aria-hidden="true"
  >
    <path d="M12 3v9M6.3 5.8a9 9 0 1 0 11.4 0" />
  </svg>
);

const Fader = ({
  label,
  value,
  min,
  max,
  step,
  unit,
  onChange,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  unit: string;
  onChange: (value: number) => void;
}) => (
  <FaderControl>
    <FaderSlot>
      <Scale aria-hidden="true">
        <span>{formatScale(max, unit)}</span>
        <span>{formatScale((max + min) / 2, unit)}</span>
        <span>{formatScale(min, unit)}</span>
      </Scale>
      <FaderInput
        type="range"
        data-instrument-control="true"
        aria-label={label}
        aria-orientation="vertical"
        aria-valuetext={formatValue(value, unit)}
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={event => onChange(Number(event.target.value))}
        onPointerUp={event => event.currentTarget.blur()}
        onPointerCancel={event => event.currentTarget.blur()}
      />
    </FaderSlot>
    <FaderLabel>{shortLabels[label] ?? label}</FaderLabel>
  </FaderControl>
);

export const InstrumentEffects = ({
  guitar,
  open: controlledOpen,
  onOpenChange,
  inline = false,
}: {
  guitar: ReturnType<typeof useGuitarInput>;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  inline?: boolean;
}) => {
  const dispatch = useDispatch();
  const { timbre, isRecording } = useSelector(selectSettings);
  const [live, setLive] = useState(() => loadAudioRouting().live);
  const liveEffects = live && (guitar.inputSound ?? 'effects') === 'effects';
  const effectsKey = liveEffects ? LIVE_INPUT_EFFECTS_KEY : timbre;
  const output = useAudioOutput(guitar.outputs, guitar.devicesReady);
  const { instruments } = useSelector(selectEffects);
  const settings = instruments[effectsKey] ?? defaultEffects(effectsKey);
  const [localOpen, setLocalOpen] = useState(false);
  const open = controlledOpen ?? localOpen;
  const setOpen = useCallback(
    (next: boolean) => (onOpenChange ?? setLocalOpen)(next),
    [onOpenChange],
  );
  const trigger = useRef<HTMLButtonElement>(null);
  const closeButton = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLElement>(null);
  const close = () => {
    setOpen(false);
    trigger.current?.focus();
  };

  useHeaderPopupDismiss(open, setOpen, trigger, panel);

  useEffect(() => {
    if (!open) return;
    closeButton.current?.focus();
  }, [open, setOpen]);

  const update = (next: typeof settings) => {
    if (liveEffects) guitar.updateLiveEffects(next);
    else dispatch(effectsActions.setInstrument({ timbre, settings: next }));
  };
  const updateEffect = (
    name: EffectName,
    key: string,
    value: number | boolean,
  ) => {
    update({
      ...settings,
      [name]: {
        ...settings[name],
        [key]: value,
        enabled: key === 'enabled' ? Boolean(value) : true,
      },
    });
  };
  const activeCount = effectNames.filter(name => settings[name].enabled).length;
  const activePedals = (settings.pedals ?? []).filter(
    pedal => pedal.enabled,
  ).length;

  return (
    <>
      {!inline && (
        <Trigger
          ref={trigger}
          type="button"
          aria-expanded={open}
          aria-controls="instrument-effects"
          aria-haspopup="dialog"
          aria-label="Effects"
          title={`Effects${activeCount > 0 ? `: enabled ${activeCount}` : ''}${
            activePedals > 0 ? `. Pedals: ${activePedals}` : ''
          }${settings.bypass ? '. Bypass is on' : ''}`}
          data-active={
            (activeCount > 0 || activePedals > 0) && !settings.bypass
          }
          onClick={() => (open ? close() : setOpen(true))}
        >
          <HeaderIcon name="effects" />
        </Trigger>
      )}
      {(open || inline) && (
        <Panel
          $inline={inline}
          $width={1240}
          ref={panel}
          id={inline ? undefined : 'instrument-effects'}
          role={inline ? undefined : 'dialog'}
          aria-label="Instrument effects"
        >
          <Toolbar>
            <BypassButton
              type="button"
              aria-label="Bypass all effects"
              title="Temporarily disables processing while preserving effect settings."
              aria-pressed={settings.bypass}
              onClick={() => update({ ...settings, bypass: !settings.bypass })}
            >
              <PowerIcon />
              Bypass
            </BypassButton>
            <ChainStatus role="status" aria-label="Chain status">
              {settings.bypass
                ? 'Unprocessed'
                : `Enabled effects: ${activeCount} / ${effectNames.length}${
                    settings.pedals?.length
                      ? ` · Pedals: ${activePedals} / ${settings.pedals.length}`
                      : ''
                  }`}
            </ChainStatus>
            <ResetButton
              type="button"
              onClick={() => update(defaultEffects(effectsKey))}
            >
              Reset settings
            </ResetButton>
            {!inline && (
              <CloseButton
                ref={closeButton}
                type="button"
                onClick={close}
                aria-label="Close effects"
              >
                <span aria-hidden="true">×</span>
              </CloseButton>
            )}
          </Toolbar>
          <EffectsRouting
            guitar={guitar}
            live={live}
            onLiveChange={value => {
              setLive(value);
              saveAudioRouting({ live: value });
            }}
            output={output}
            recording={isRecording}
          />
          <EffectPresets
            key={effectsKey}
            settings={settings}
            onChange={update}
          />
          <Mixer>
            <EffectsBank role="group" aria-label="Effect chain">
              {effectNames.map(name => {
                const { title, description, controls } =
                  effectDefinitions[name];
                const effect = settings[name];
                return (
                  <Channel
                    key={name}
                    role="group"
                    aria-label={title}
                    title={description}
                    $processing={effect.enabled && !settings.bypass}
                    $wide={controls.length > 3}
                  >
                    <ChannelTop>
                      <EffectSwitch
                        type="button"
                        aria-label={title}
                        aria-pressed={effect.enabled}
                        onClick={() =>
                          updateEffect(name, 'enabled', !effect.enabled)
                        }
                      >
                        <PowerIcon />
                      </EffectSwitch>
                      <ChannelTitle>{title}</ChannelTitle>
                      <EffectIndicator
                        aria-hidden="true"
                        $active={effect.enabled && !settings.bypass}
                        title={
                          settings.bypass && effect.enabled
                            ? 'Effect bypassed'
                            : effect.enabled
                            ? 'Effect on'
                            : 'Effect off'
                        }
                      />
                    </ChannelTop>
                    {name === 'wah' && (
                      <WahControl settings={settings} onChange={update} />
                    )}
                    <Faders>
                      {controls.map(({ key, ...control }) => (
                        <Fader
                          key={key}
                          {...control}
                          value={
                            (effect as unknown as Record<string, number>)[key]
                          }
                          onChange={value => updateEffect(name, key, value)}
                        />
                      ))}
                    </Faders>
                  </Channel>
                );
              })}
            </EffectsBank>
            <Master
              role="group"
              aria-label="Instrument output"
              title="This browser saves effects separately for each instrument. You’ll hear them when playing live or listening back. Melody files do not store these settings."
            >
              <MasterHeading>
                <span aria-hidden="true">OUT</span>
                <strong>Output</strong>
              </MasterHeading>
              <Faders>
                <Fader
                  label={
                    liveEffects ? 'Audio input volume' : 'Instrument volume'
                  }
                  value={settings.volume}
                  min={0}
                  max={maxEffectsVolume(effectsKey)}
                  step={1}
                  unit="%"
                  onChange={volume => update({ ...settings, volume })}
                />
              </Faders>
            </Master>
          </Mixer>
        </Panel>
      )}
    </>
  );
};

