import { PayloadAction } from '@reduxjs/toolkit';

import { createSlice, useInjectReducer } from 'utils';

import { KeyCode } from '../types';
import { KeyboardState } from './types';

export const initialState: KeyboardState = {
  pressedKeys: [],
  previouslyPressedKey: null,
  previouslyUnpressedKey: null,
};

const slice = createSlice({
  name: 'keyboard',
  initialState,
  reducers: {
    addPressedKey(state, action: PayloadAction<KeyCode>) {
      if (state.pressedKeys.includes(action.payload)) {
        return;
      }
      state.previouslyUnpressedKey = null;
      state.previouslyPressedKey = action.payload;
      state.pressedKeys.push(action.payload);
    },
    removePressedKey(state, action: PayloadAction<KeyCode>) {
      if (!state.pressedKeys.includes(action.payload)) {
        return;
      }
      state.previouslyPressedKey = null;
      state.previouslyUnpressedKey = action.payload;
      state.pressedKeys = state.pressedKeys.filter(
        note => note !== action.payload,
      );
    },
    resetPressedKeys(state) {
      state.pressedKeys = [];
      state.previouslyPressedKey = null;
      state.previouslyUnpressedKey = null;
    },
  },
});

export const { actions: keyboardActions } = slice;

export const useKeyboardSlice = () => {
  useInjectReducer({ key: slice.name, reducer: slice.reducer });
  return { actions: slice.actions };
};
