import styled from 'styled-components';

import { NoiseGateSettings } from 'app/services/GuitarInputService/noiseGateSettings';

export const NoiseGateControls = ({
  settings,
  onChange,
}: {
  settings: NoiseGateSettings;
  onChange: (value: NoiseGateSettings) => void;
}) => (
  <Controls aria-label="Audio input noise gate">
    <legend>
      <Toggle>
        <input
          type="checkbox"
          aria-label="Input noise gate"
          checked={settings.enabled}
          onChange={event =>
            onChange({ ...settings, enabled: event.target.checked })
          }
        />
        Noise gate
      </Toggle>
    </legend>
    <Fields>
      <label>
        Threshold: {settings.threshold} dBFS
        <input
          type="range"
          aria-label="Noise gate threshold"
          min={-80}
          max={-10}
          step={1}
          data-instrument-control="true"
          disabled={!settings.enabled}
          value={settings.threshold}
          aria-valuetext={`${settings.threshold} dBFS`}
          onChange={event =>
            onChange({ ...settings, threshold: Number(event.target.value) })
          }
        />
      </label>
      <label>
        Release: {settings.release} ms
        <input
          type="range"
          aria-label="Noise gate release"
          min={20}
          max={1000}
          step={10}
          data-instrument-control="true"
          disabled={!settings.enabled}
          value={settings.release}
          aria-valuetext={`${settings.release} ms`}
          onChange={event =>
            onChange({ ...settings, release: Number(event.target.value) })
          }
        />
      </label>
    </Fields>
    <p>
      Reduces background noise between notes before distortion and other
      effects. Raise the threshold until noise disappears: too high a threshold
      cuts off quiet notes. Release smooths the closing. The original recording
      is saved without the gate.
    </p>
  </Controls>
);

const Controls = styled.fieldset`
  min-width: 0;
  margin: 12px 0;
  padding: 10px 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  font-size: 12px;
  legend {
    padding: 0 6px;
  }
  p {
    color: ${p => p.theme.textSecondary};
    line-height: 1.5;
    margin-bottom: 0;
  }
  input[type='range'] {
    width: 100%;
  }
`;
const Toggle = styled.label`
  display: inline-flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 8px;
  margin: 0 !important;
`;
const Fields = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  label {
    display: flex;
    flex-direction: column;
    flex: 1 1 180px;
    min-width: 0;
    gap: 6px;
  }
`;
