import type { InstrumentEffects } from 'app/services/EffectsService/settings';

import type { Melody } from '../MelodiesService/types';
import { encodeMidi } from './midi';
import { ScoreExportFormat, isScoreFormat, scoreFormats } from './scoreFormats';

export type ExportFormat = 'midi' | 'wav' | 'mp3' | ScoreExportFormat;
export type ExportOptions = { optimizeTablature?: boolean | 'composition' };
const extensions: Record<ExportFormat, string> = {
  midi: 'mid',
  wav: 'wav',
  mp3: 'mp3',
  pdf: 'pdf',
  'pdf-guitar': 'pdf',
  'pdf-guitar-drop-d': 'pdf',
  'pdf-bass': 'pdf',
  'pdf-ukulele': 'pdf',
};

export const getExportFilename = (melody: Melody, format: ExportFormat) => {
  const raw = [melody.author, melody.displayTitle ?? melody.title]
    .filter(Boolean)
    .join(' - ');
  const title = Array.from(raw, char =>
    char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127 ? '_' : char,
  )
    .join('')
    .replace(/[<>:"/\\|?*]/g, '_')
    .replace(/[.\s]+$/g, '')
    .trim()
    .slice(0, 120);
  const safe =
    title && !/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(title)
      ? title
      : 'melody-generator-recording';
  const suffix = isScoreFormat(format) ? `-${scoreFormats[format].suffix}` : '';
  return `${safe}${suffix}.${extensions[format]}`;
};

export const createMelodyExport = async (
  melody: Melody,
  format: ExportFormat,
  effects?: InstrumentEffects,
  options?: ExportOptions,
): Promise<Blob> => {
  if (isScoreFormat(format)) {
    const { createScorePdf } = await import('./score');
    return createScorePdf(melody, format, options?.optimizeTablature);
  }
  if (format === 'midi')
    return new Blob([encodeMidi(melody)], { type: 'audio/midi' });
  const { renderMelodyAudio, encodeWav } = await import('./audio');
  const audio = await renderMelodyAudio(melody, effects);
  if (format === 'wav')
    return new Blob([encodeWav(audio)], { type: 'audio/wav' });
  const { encodeMp3 } = await import('./mp3');
  return encodeMp3(audio);
};

export const downloadMelody = async (
  melody: Melody,
  format: ExportFormat,
  effects?: InstrumentEffects,
  options?: ExportOptions,
) => {
  const blob = await createMelodyExport(melody, format, effects, options);
  downloadBlob(blob, getExportFilename(melody, format));
};

export const downloadBlob = (blob: Blob, filename: string) => {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  try {
    link.click();
  } finally {
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
};
