import { Midi } from '@tonejs/midi';

import type { Melody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNote } from 'app/services/NotesService/noteUtils';
import type { Octave } from 'app/services/NotesService/types';

import { Phrase, STEPS_PER_BEAT } from './compose';

const timeSignature = '4/4';
const title = 'Generated melody';

export const phrasePlayback = (phrase: Phrase): Melody => {
  const stepMs = 60000 / (phrase.bpm * STEPS_PER_BEAT);
  return {
    title,
    timbre: 'studioResonantPiano',
    scale: 'diatonic',
    mode: phrase.mode === 'minor' ? 'aeolian' : 'ionian',
    pitch: phrase.pitch,
    octave: 4,
    bpm: phrase.bpm,
    timeSignature,
    notes: [...phrase.melody, ...phrase.accompaniment].map(note => ({
      note: getNote(
        chromaticNotes[note.midi % 12],
        (Math.floor(note.midi / 12) - 1) as Octave,
      ),
      start: note.start * stepMs,
      duration: (note.start + note.length) * stepMs - note.start * stepMs,
    })),
  };
};

export const encodePhraseMidi = (phrase: Phrase): Uint8Array => {
  const midi = new Midi();
  midi.header.name = title;
  midi.header.timeSignatures.push({ ticks: 0, timeSignature: [4, 4] });
  midi.header.setTempo(phrase.bpm);
  const stepTicks = midi.header.ppq / STEPS_PER_BEAT;
  const parts = [
    { name: 'Melody', notes: phrase.melody, velocity: 0.8 },
    { name: 'Accompaniment', notes: phrase.accompaniment, velocity: 0.58 },
  ];
  parts.forEach(({ name, notes, velocity }, channel) => {
    const track = midi.addTrack();
    track.name = name;
    track.channel = channel;
    notes.forEach(note =>
      track.addNote({
        midi: note.midi,
        ticks: note.start * stepTicks,
        durationTicks: note.length * stepTicks,
        velocity,
      }),
    );
  });
  return midi.toArray();
};
