import { keyboardButtons } from 'app/services/KeyboardService/mappings';
import { KeyCode } from 'app/services/KeyboardService/types';
import { Melody } from 'app/services/MelodiesService/types';
import { Note } from 'app/services/NotesService/types';

// Colors belong to physical rows, independent of a song's pitch range.
import { noteColors } from 'styles/theme/noteColors';

import { getNoteBindings } from './game';

const rowColors = noteColors.keyboardRows;
const unmappedColor = noteColors.unmapped;

export type KeyboardTarget = {
  id: string;
  label: string;
  note?: Note;
  left: number;
  width: number;
  color: string;
};
export type KeyboardTrack = {
  id: string;
  label: string;
  legend: string;
  color: string;
  targets: KeyboardTarget[];
};
type PhysicalKey = [string, string?, number?];

// A normal 15-unit ANSI keyboard. Geometry is independent of musical bindings.
const physicalRows: PhysicalKey[][] = [
  [
    ['Backquote', '`'],
    ...Array.from(
      { length: 10 },
      (_, i): PhysicalKey => [`Digit${(i + 1) % 10}`],
    ),
    ['Minus'],
    ['Equal'],
    ['Backspace', '⌫', 2],
  ],
  [
    ['Tab', 'Tab', 1.5],
    ...['Q', 'W', 'E', 'R', 'T', 'Y', 'U', 'I', 'O', 'P'].map(
      (letter): PhysicalKey => [`Key${letter}`],
    ),
    ['BracketLeft'],
    ['BracketRight'],
    ['Backslash', undefined, 1.5],
  ],
  [
    ['CapsLock', 'Caps', 1.75],
    ...['A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L'].map(
      (letter): PhysicalKey => [`Key${letter}`],
    ),
    ['Semicolon'],
    ['Quote'],
    ['Enter', 'Enter', 2.25],
  ],
  [
    ['ShiftLeft', 'Shift', 2.25],
    ...['Z', 'X', 'C', 'V', 'B', 'N', 'M'].map(
      (letter): PhysicalKey => [`Key${letter}`],
    ),
    ['Comma'],
    ['Period'],
    ['Slash'],
    ['ShiftRight', 'Shift', 2.75],
  ],
  [['Space', 'Space', 6.25]],
];

export const getKeyboardLayout = (
  notes: Melody['notes'],
  settings: Parameters<typeof getNoteBindings>[0],
) => {
  const bindings = getNoteBindings(settings);
  const notesByKey = new Map(
    Array.from(bindings, ([note, key]) => [key, note]),
  );
  const labels = ['Number row', 'Q row', 'A row', 'Z row', 'Space'];
  const rows: KeyboardTrack[] = physicalRows.map((row, i) => {
    let offset = i === 4 ? 3.75 : 0;
    return {
      id: `row-${i * 30}`,
      label: labels[i],
      legend: ['1–0', 'Q', 'A', 'Z', 'Space'][i],
      color: rowColors[i],
      targets: row.map(([id, label, units = 1]) => {
        const note = notesByKey.get(id as KeyCode);
        const target = {
          id,
          label: label ?? keyboardButtons[id]?.title ?? id,
          note,
          left: (offset / 15) * 100,
          width: (units / 15) * 100,
          color: rowColors[i],
        };
        offset += units;
        return target;
      }),
    };
  });
  const missing = Array.from(new Set(notes.map(({ note }) => note))).filter(
    note => !bindings.has(note),
  );
  if (missing.length)
    rows.push({
      id: 'unmapped',
      label: 'Notes outside the layout · play on screen',
      legend: 'Screen',
      color: unmappedColor,
      targets: missing.map((note, i) => ({
        id: note,
        label: note,
        note,
        left: (i / missing.length) * 100,
        width: 100 / missing.length,
        color: unmappedColor,
      })),
    });
  return { rows, minWidth: Math.max(480, missing.length * 40) };
};
