import {
  PointerEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from 'react';
import styled from 'styled-components';

import type { Note } from 'app/services/NotesService/types';
import {
  isInstrumentAudioRunning,
  loadSound,
  playLiveExpressiveNote,
  resumeAudio,
} from 'app/services/SynthesizerService';

import { DemoHint, DemoStatus, DemoSurface } from './LandingDemoStyles';

const timbre = 'studioResonantPiano';
const tapDuration = 200;

const whiteKeys = [
  { note: 'C4', shortcut: 'A' },
  { note: 'D4', shortcut: 'S' },
  { note: 'E4', shortcut: 'D' },
  { note: 'F4', shortcut: 'F' },
  { note: 'G4', shortcut: 'J' },
  { note: 'A4', shortcut: 'K' },
  { note: 'B4', shortcut: 'L' },
  { note: 'C5', shortcut: 'Q' },
] as const;

const blackKeys = [
  { note: 'C#4', step: 1 },
  { note: 'D#4', step: 2 },
  { note: 'F#4', step: 4 },
  { note: 'G#4', step: 5 },
  { note: 'A#4', step: 6 },
] as const;

const scorePositions = {
  C4: 140,
  'C#4': 140,
  D4: 132,
  'D#4': 132,
  E4: 124,
  F4: 116,
  'F#4': 116,
  G4: 108,
  'G#4': 108,
  A4: 100,
  'A#4': 100,
  B4: 92,
  C5: 84,
};
type PianoNote = keyof typeof scorePositions;
type PlayedNote = { note: PianoNote; id: number };
type Press = PlayedNote & {
  released: boolean;
  unlockOnRelease: boolean;
  stop?: () => void;
  timer?: number;
};

const example = whiteKeys.map(({ note }, index) => ({ note, id: -index - 1 }));

const noteName = (note: Note) => note.replace('#', ' sharp ');

export const LandingPiano = ({ visible = true }: { visible?: boolean }) => {
  const hintId = useId();
  const group = useRef<HTMLDivElement>(null);
  const presses = useRef(new Map<string, Press>());
  const pianoPointers = useRef(new Set<number>());
  const nextNoteId = useRef(0);
  const [score, setScore] = useState<PlayedNote[]>([]);
  const [active, setActive] = useState<Press[]>([]);
  const [status, setStatus] = useState<'idle' | 'loading' | 'ready' | 'error'>(
    'idle',
  );

  const clearPresses = useCallback(() => {
    presses.current.forEach(press => {
      window.clearTimeout(press.timer);
      press.stop?.();
    });
    presses.current.clear();
    pianoPointers.current.clear();
  }, []);

  const reset = useCallback(() => {
    clearPresses();
    setActive([]);
    setStatus(current => (current === 'loading' ? 'idle' : current));
  }, [clearPresses]);

  useEffect(() => {
    if (!visible) {
      reset();
      return;
    }
    // Reuse the pending download on the first note. A failed preload can be
    // retried from the key handler.
    void loadSound(timbre).catch(() => {});
    if (!window.location.hash && document.activeElement === document.body) {
      group.current?.focus({ preventScroll: true });
    }
  }, [visible, reset]);

  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.hidden) reset();
    };
    window.addEventListener('blur', reset);
    window.addEventListener('pagehide', reset);
    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      clearPresses();
      window.removeEventListener('blur', reset);
      window.removeEventListener('pagehide', reset);
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [clearPresses, reset]);

  const cancel = (input: string) => {
    const press = presses.current.get(input);
    if (!press) return;
    presses.current.delete(input);
    window.clearTimeout(press.timer);
    if (!presses.current.size) {
      setStatus(current => (current === 'loading' ? 'idle' : current));
    }
    if (press.stop) {
      press.stop();
      setActive(current => current.filter(note => note !== press));
    }
  };

  const sound = (input: string, press: Press) => {
    setStatus(current => (current === 'ready' ? current : 'loading'));
    // Unlock synchronously in the input event, before waiting for the sample.
    void Promise.all([resumeAudio(), loadSound(timbre)])
      .then(() => {
        if (presses.current.get(input) !== press) return;
        const voice = playLiveExpressiveNote(timbre, press.note);
        if (!voice) throw new Error('Piano note unavailable');
        press.stop = voice.stop;
        setActive(current => [...current, press]);
        const { note, id } = press;
        setScore(current => [...current.slice(-7), { note, id }]);
        setStatus('ready');
        if (press.released) {
          press.timer = window.setTimeout(() => cancel(input), tapDuration);
        }
      })
      .catch(() => {
        if (presses.current.get(input) !== press) return;
        cancel(input);
        setStatus('error');
      });
  };

  const play = (
    input: string,
    note: PianoNote,
    released = false,
    unlockOnRelease = false,
  ) => {
    cancel(input);
    const press = { note, id: ++nextNoteId.current, released, unlockOnRelease };
    presses.current.set(input, press);
    if (!unlockOnRelease) sound(input, press);
  };

  const release = (input: string) => {
    const press = presses.current.get(input);
    if (!press) return;
    if (press.stop) {
      cancel(input);
    } else {
      press.released = true;
      if (press.unlockOnRelease) {
        press.unlockOnRelease = false;
        sound(input, press);
      }
    }
  };

  const isPlaying = (note: PianoNote) =>
    active.some(press => press.note === note);

  const pointerEnd = {
    onPointerUp: (event: PointerEvent<Element>) => {
      pianoPointers.current.delete(event.pointerId);
      release(`pointer:${event.pointerId}`);
    },
    onPointerCancel: (event: PointerEvent<Element>) => {
      pianoPointers.current.delete(event.pointerId);
      cancel(`pointer:${event.pointerId}`);
    },
    onLostPointerCapture: (event: PointerEvent<Element>) => {
      pianoPointers.current.delete(event.pointerId);
      const input = `pointer:${event.pointerId}`;
      if (!presses.current.get(input)?.released) cancel(input);
    },
  };

  const pianoNoteAt = (element: Element | null, piano: HTMLDivElement) => {
    const button = element?.closest<HTMLButtonElement>(
      'button[data-piano-note]',
    );
    return button && piano.contains(button)
      ? (button.dataset.pianoNote as PianoNote)
      : undefined;
  };

  const playPointerNote = (event: PointerEvent<Element>, note: PianoNote) => {
    // The first touch may only unlock audio when the finger is lifted.
    const unlockOnRelease =
      event.pointerType !== 'mouse' && !isInstrumentAudioRunning();
    play(`pointer:${event.pointerId}`, note, false, unlockOnRelease);
  };

  const pianoKey = (note: PianoNote, shortcut?: string) => ({
    'data-piano-note': note,
    type: 'button' as const,
    'aria-label': `Play ${noteName(note)}`,
    'aria-keyshortcuts': shortcut,
    'data-playing': isPlaying(note),
    onClick: (event: React.MouseEvent<HTMLButtonElement>) => {
      if (event.detail === 0) play(`click:${note}`, note, true);
    },
  });

  return (
    <div
      ref={group}
      role="group"
      tabIndex={-1}
      aria-label="Piano"
      aria-describedby={hintId}
      onBlur={event => {
        if (!event.currentTarget.contains(event.relatedTarget)) reset();
      }}
      onKeyDown={event => {
        if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey)
          return;
        const key = whiteKeys.find(
          ({ shortcut }) => event.code === `Key${shortcut}`,
        );
        if (key && !event.repeat) play(event.code, key.note);
      }}
      onKeyUp={event => release(event.code)}
    >
      <Score aria-hidden="true">
        <svg viewBox="0 0 440 177" focusable="false" {...pointerEnd}>
          <path
            d="M16 60H424M16 76H424M16 92H424M16 108H424M16 124H424"
            stroke="#5c827f"
            strokeOpacity=".65"
          />
          <path d="M424 60v64" stroke="#5c827f" />
          {(score.length ? score : example).map(({ note, id }, index) => {
            const x = 34 + 52 * index;
            const y = scorePositions[note];
            const playing = active.some(press => press.id === id);
            return (
              <g
                key={id}
                data-note={note}
                data-playing={playing}
                fill={playing ? '#57d7bd' : '#a4c4bd'}
                onPointerDown={event => {
                  if (event.button !== 0 || event.pointerType !== 'mouse')
                    return;
                  event.preventDefault();
                  event.currentTarget.ownerSVGElement?.setPointerCapture?.(
                    event.pointerId,
                  );
                  playPointerNote(event, note);
                }}
              >
                <text
                  x={x}
                  y="35"
                  textAnchor="middle"
                  fontFamily="monospace"
                  fontSize="14"
                  fontWeight="700"
                >
                  {note.slice(0, -1).replace('#', '♯')}
                </text>
                <rect
                  x={x - 20}
                  y={y - 36}
                  width="31"
                  height="45"
                  fill="transparent"
                />
                {y === 140 && (
                  <path d={`M${x - 10} ${y}h20`} stroke="currentColor" />
                )}
                {note.includes('#') && (
                  <text x={x - 19} y={y + 5} fontSize="17">
                    ♯
                  </text>
                )}
                <ellipse
                  cx={x}
                  cy={y}
                  rx="8"
                  ry="5.5"
                  transform={`rotate(-19 ${x} ${y})`}
                />
                <path d={`M${x + 6} ${y}v-35h1.6v35Z`} />
              </g>
            );
          })}
        </svg>
      </Score>
      <Piano
        {...pointerEnd}
        onPointerDown={event => {
          if (
            event.button !== 0 ||
            !(event.target instanceof HTMLButtonElement)
          )
            return;
          const note = pianoNoteAt(event.target, event.currentTarget);
          if (!note) return;
          event.preventDefault();
          event.target.focus({ preventScroll: true });
          event.currentTarget.setPointerCapture?.(event.pointerId);
          pianoPointers.current.add(event.pointerId);
          playPointerNote(event, note);
        }}
        onPointerMove={event => {
          if (!pianoPointers.current.has(event.pointerId)) return;
          const input = `pointer:${event.pointerId}`;
          const note = pianoNoteAt(
            document.elementFromPoint(event.clientX, event.clientY),
            event.currentTarget,
          );
          if (note === presses.current.get(input)?.note) return;
          if (note) playPointerNote(event, note);
          else cancel(input);
        }}
      >
        <WhiteKeys>
          {whiteKeys.map(({ note, shortcut }) => (
            <WhiteKey key={note} {...pianoKey(note, shortcut)}>
              {shortcut}
            </WhiteKey>
          ))}
        </WhiteKeys>
        {blackKeys.map(({ note, step }) => (
          <BlackKey
            key={note}
            {...pianoKey(note)}
            style={{ left: `${step * 12.5}%` }}
          />
        ))}
      </Piano>
      <DemoHint id={hintId}>
        Press the letters shown, tap a key, or drag across the piano.
      </DemoHint>
      <DemoStatus role="status">
        {status === 'loading' && 'Loading piano sound…'}
        {status === 'error' && 'Sound could not start. Try a key again.'}
      </DemoStatus>
    </div>
  );
};

const Score = styled(DemoSurface)`
  margin-bottom: 10px;
  background: linear-gradient(90deg, #9abeb616 1px, transparent 1px) 0 0 / 12.5%
      100%,
    #0d1c2266;

  g {
    cursor: pointer;
  }

  svg {
    display: block;
    width: 100%;
    height: auto;
  }
`;

const Piano = styled.div`
  position: relative;
  touch-action: none;
  border-radius: 5px;
`;

const WhiteKeys = styled.div`
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 2px;
`;

const PianoButton = styled.button`
  padding: 0;
  min-height: 0;
  border: 0;
  user-select: none;
  touch-action: none;

  &:focus-visible {
    z-index: 1;
    outline-color: #57d7bd;
    outline-offset: -3px;
  }
`;

const WhiteKey = styled(PianoButton)`
  display: grid;
  align-items: end;
  justify-items: center;
  height: clamp(54px, 10vw, 108px);
  padding-bottom: 6px;
  border-radius: 0 0 4px 4px;
  background: #e2f1ec;

  &:hover {
    background: #c5e2dc;
  }

  &[data-playing='true'] {
    background: #57d7bd;
  }
  color: #16363d;
  font: 700 0.6875rem/1.5 ui-monospace, monospace;
`;

const BlackKey = styled(PianoButton)`
  position: absolute;
  top: 0;
  width: 7%;
  height: 60%;
  transform: translateX(-50%);
  border-radius: 0 0 4px 4px;
  z-index: 1;
  box-shadow: inset 0 -3px #35525b;
  background: #0d1c22;

  &:hover {
    background: #22434a;
  }

  &[data-playing='true'] {
    background: #57d7bd;
  }
`;
